def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    total_opp_def = 0
    for a, b in history:
        if b == 'D':
            total_opp_def += 1

    if (n == 25 or n == 55) and total_opp_def == 0 and opp[-1] == 'C' and me[-1] == 'C':
        return 'D'

    after_c = 0
    after_c_d = 0
    after_d = 0
    after_d_d = 0
    for i in range(n - 1):
        if me[i] == 'C':
            after_c += 1
            if opp[i + 1] == 'D':
                after_c_d += 1
        else:
            after_d += 1
            if opp[i + 1] == 'D':
                after_d_d += 1

    recent_len = n if n < 10 else 10
    recent_d = 0
    start = n - recent_len
    for i in range(start, n):
        if opp[i] == 'D':
            recent_d += 1
    recent_d = recent_d / float(recent_len)
    overall_d = total_opp_def / float(n)

    q_c = (after_c_d + 1.0) / (after_c + 7.0)
    q_d = (after_d_d + 9.0) / (after_d + 11.0)

    if total_opp_def == 0 and after_d_d == 0:
        if after_d >= 2:
            q_d = 0.20
        elif after_d >= 1:
            q_d = 0.50

    if after_d >= 2 and after_d_d >= 1:
        q_d = max(q_d, 0.75)
        q_c = max(q_c, 0.65)

    if recent_d > 0.3:
        floor = 0.25 + 0.55 * recent_d
        q_c = max(q_c, floor)
        q_d = max(q_d, floor)
    elif overall_d > 0.5:
        floor = 0.20 + 0.50 * overall_d
        q_c = max(q_c, floor)
        q_d = max(q_d, floor)

    if q_c < 0.04:
        q_c = 0.04
    if q_c > 0.96:
        q_c = 0.96
    if q_d < 0.04:
        q_d = 0.04
    if q_d > 0.96:
        q_d = 0.96

    q_now = q_c if me[-1] == 'C' else q_d

    opp_d_streak = 0
    i = n - 1
    while i >= 0 and opp[i] == 'D':
        opp_d_streak += 1
        i -= 1

    if opp_d_streak >= 3:
        q_now = max(q_now, 0.85)
    elif opp_d_streak == 2:
        q_now = max(q_now, 0.65)
    elif opp_d_streak == 1 and me[-1] == 'C' and recent_d > 0.5:
        q_now = max(q_now, 0.65)

    if q_now < 0.02:
        q_now = 0.02
    if q_now > 0.98:
        q_now = 0.98

    m = 100 - n
    vc = [0.0] * (m + 1)
    vd = [0.0] * (m + 1)

    for k in range(1, m + 1):
        c_c = 3.0 - 3.0 * q_c + vc[k - 1]
        d_c = 5.0 - 4.0 * q_c + vd[k - 1]
        if c_c >= d_c:
            vc[k] = c_c
        else:
            vc[k] = d_c

        c_d = 3.0 - 3.0 * q_d + vc[k - 1]
        d_d = 5.0 - 4.0 * q_d + vd[k - 1]
        if c_d >= d_d:
            vd[k] = c_d
        else:
            vd[k] = d_d

    val_c = 3.0 - 3.0 * q_now + vc[m - 1]
    val_d = 5.0 - 4.0 * q_now + vd[m - 1]

    if val_d > val_c:
        return 'D'
    return 'C'
